"""The optional producer hooks must preserve all original generated bytes."""
from pathlib import Path
import importlib.util
import tempfile

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("post_lift", ROOT / "scripts/post_lift.py")
patcher = importlib.util.module_from_spec(spec)
spec.loader.exec_module(patcher)


def run():
    with tempfile.TemporaryDirectory() as temp:
        path = Path(temp) / "fixture.cpp"
        for nl in (b"\n", b"\r\n"):
            original = b"// legacy \x96 comment" + nl
            additions = []
            for address, site in patcher.GEOMETRY_PRODUCER_SITES.items():
                original += ("void func_%s(ppu_context* ctx) {" % address).encode() + nl
                original += b"        ctx->gpr[3] += 1;" + nl + b"}" + nl
                additions.append(nl.join(line.encode() for line in (
                    "        /* tj-geometry-producer-trace */",
                    "        extern void tj_geometry_producer_trace(ppu_context*, uint32_t);",
                    "        tj_geometry_producer_trace(ctx, %d);" % site, "")))
            path.write_bytes(original)
            assert patcher.patch_geometry_producer_file(path) == len(patcher.GEOMETRY_PRODUCER_SITES)
            patched = path.read_bytes()
            restored = patched
            for addition in additions:
                assert restored.count(addition) == 1
                restored = restored.replace(addition, b"")
            assert restored == original, "generated bytes changed outside trace hooks"
            assert patcher.patch_geometry_producer_file(path) == 0
            assert path.read_bytes() == patched
        path.write_bytes(original + original)
        try:
            patcher.patch_geometry_producer_file(path)
        except RuntimeError:
            pass
        else:
            raise AssertionError("ambiguous function accepted")
        assert path.read_bytes() == original + original
    print("PASS: LF/CRLF, non-UTF8, exact preservation, idempotence, ambiguous-input rejection")


if __name__ == "__main__":
    run()
